urlset:
{%- for file in pages -%}
    {% if not file.page.is_link and (file.page.abs_url or file.page.canonical_url) %}

         {% if file.page.canonical_url %}{{ file.page.canonical_url|e }}{% else %}{{ file.page.abs_url|e }}{% endif %}
         {% if file.page.meta and file.page.meta.zi_modified %}{{ file.page.meta.zi_modified[:10] }}{% elif file.page.update_date %}{{ file.page.update_date }}{% endif %}

    {%- endif -%}
{% endfor %}
